func discoverProvider(ctx context.Context, providerName string, pc ProviderConfig, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	providerType := normalizeProviderType(pc.Type)
	switch providerType {
	case "claude", "codex":
		return discoverHarnessProvider(providerName, providerType, cache, opts)
	case "openai", "openrouter", "vidar-ds4", "sindri-llamacpp", "ds4", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
		result := discoverOpenAICompatibleProvider(ctx, providerName, pc, cache, opts)
		if providerType == "ds4" || providerType == "vidar-ds4" {
			result.merge(discoverPropsProvider(providerName, pc, cache))
		}
		return result
	default:
		if strings.TrimSpace(pc.Model) == "" {
			return providerDiscoveryResult{Sources: map[string]SourceMeta{}}
		}
		return providerDiscoveryResult{
			Models: []discoveredModel{{
				Provider:        providerName,
				ProviderType:    providerType,
				ID:              strings.TrimSpace(pc.Model),
				EndpointName:    endpointNameForConfig(providerName, pc.BaseURL, pc.Endpoints),
				EndpointBaseURL: firstBaseURL(pc),
				ServerInstance:  firstServerInstance(pc),
				Via:             SourceNativeAPI,
				DiscoveredAt:    time.Now().UTC(),
			}},
			Sources: map[string]SourceMeta{
				providerName: {LastRefreshedAt: time.Now().UTC()},
			},
		}
	}
}

func discoverOpenAICompatibleProvider(ctx context.Context, providerName string, pc ProviderConfig, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	if cache == nil {
		return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName: {Stale: true, Error: "discovery cache is nil"}}}
	}
	endpoints := discoveryEndpoints(providerName, pc)
	if len(endpoints) == 0 {
		endpoints = []modelDiscoveryEndpoint{{
			Name:           endpointNameForConfig(providerName, pc.BaseURL, nil),
			BaseURL:        firstBaseURL(pc),
			ServerInstance: firstServerInstance(pc),
		}}
	}
	result := providerDiscoveryResult{Sources: map[string]SourceMeta{}}
	for _, endpoint := range endpoints {
		endpointResult := discoverOpenAICompatibleEndpoint(ctx, providerName, providerTypeFromProviderConfig(pc), endpoint, pc.APIKey, discoveryTTLForProvider(pc), cache, opts)
		result.merge(endpointResult)
	}
	if len(result.Models) == 0 && strings.TrimSpace(pc.Model) != "" {
		fallback := modelsFromIDs([]string{pc.Model}, SourceNativeAPI, time.Now().UTC(), discoveryIdentity{
			Provider:        providerName,
			ProviderType:    providerTypeFromProviderConfig(pc),
			EndpointName:    endpointNameForConfig(providerName, pc.BaseURL, pc.Endpoints),
			EndpointBaseURL: firstBaseURL(pc),
			ServerInstance:  firstServerInstance(pc),
		})
		for i := range fallback.Models {
			fallback.Models[i].Configured = true
		}
		result.merge(fallback)
		meta := result.Sources[providerName]
		if meta.LastRefreshedAt.IsZero() {
			meta.LastRefreshedAt = time.Now().UTC()
		}
		result.Sources[providerName] = meta
	}
	return result
}

func discoverOpenAICompatibleEndpoint(ctx context.Context, providerName, providerType string, endpoint modelDiscoveryEndpoint, apiKey string, ttl time.Duration, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	src := discoverySource(endpointSourceName(providerName, endpoint.Name, endpoint.BaseURL, endpoint.ServerInstance), ttl, discoveryRefreshDeadlineHTTP)
	refresher := func(refreshCtx context.Context) ([]byte, error) {
		requestCtx := ctx
		if requestCtx == nil {
			requestCtx = refreshCtx
		}
		ids, err := openaiadapter.DiscoverModels(requestCtx, strings.TrimRight(endpoint.BaseURL, "/"), apiKey)
		if err != nil {
			return nil, err
		}
		return json.Marshal(discoveryPayload{
			CapturedAt: time.Now().UTC(),
			Models:     ids,
			Source:     "openai-compatible:/v1/models",
		})
	}
	if opts.Refresh == RefreshForce {
		_ = cache.Refresh(src, refresher)
	} else if opts.Refresh != RefreshNone {
		cache.MaybeRefresh(src, refresher)
	}
	return readDiscoveryCache(cache, src, providerName, SourceNativeAPI, discoveryIdentity{
		Provider:        providerName,
		ProviderType:    providerType,
		EndpointName:    endpoint.Name,
		EndpointBaseURL: endpoint.BaseURL,
		ServerInstance:  endpoint.ServerInstance,
	})
}

func discoverPropsProvider(providerName string, pc ProviderConfig, cache *discoverycache.Cache) providerDiscoveryResult {
	if cache == nil {
		return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName + ":props": {Stale: true, Error: "discovery cache is nil"}}}
	}
	src := discoverySource(providerName+"-props", discoveryTTLHTTPLocal, discoveryRefreshDeadlineHTTP)
	result := readDiscoveryCache(cache, src, providerName, SourcePropsAPI, discoveryIdentity{
		Provider:        providerName,
		ProviderType:    providerTypeFromProviderConfig(pc),
		EndpointName:    endpointNameForConfig(providerName, pc.BaseURL, pc.Endpoints),
		EndpointBaseURL: firstBaseURL(pc),
		ServerInstance:  firstServerInstance(pc),
	})
	renamed := make(map[string]SourceMeta, len(result.Sources))
	for _, meta := range result.Sources {
		renamed[providerName+":props"] = meta
	}
	result.Sources = renamed
	return result
}

func discoverHarnessProvider(providerName, providerType string, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	src := discoverycache.Source{
		Tier:            "discovery",
		Name:            providerName,
		TTL:             discoveryTTLPTY,
		RefreshDeadline: discoveryRefreshDeadlinePTY,
	}
	if cache == nil {
		snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
		if err != nil {
			return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName: {Stale: true, Error: err.Error()}}}
		}
		return modelsFromIDs(snapshot.Models, SourceHarnessPTY, snapshot.CapturedAt, discoveryIdentity{
			Provider:       providerName,
			ProviderType:   providerType,
			Harness:        providerType,
			EndpointName:   providerName,
			ServerInstance: providerName,
		})
	}
	if opts.Refresh == RefreshForce {
		_ = cache.Refresh(src, func(context.Context) ([]byte, error) {
			snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
			if err != nil {
				return nil, err
			}
			return json.Marshal(discoveryPayload{
				CapturedAt:      snapshot.CapturedAt,
				Models:          snapshot.Models,
				ReasoningLevels: snapshot.ReasoningLevels,
				Source:          snapshot.Source,
			})
		})
	}
	result := readDiscoveryCache(cache, src, providerName, SourceHarnessPTY, discoveryIdentity{
		Provider:       providerName,
		ProviderType:   providerType,
		Harness:        providerType,
		EndpointName:   providerName,
		ServerInstance: providerName,
	})
	if len(result.Models) > 0 {
		return result
	}
	snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
	if err != nil {
		if result.Sources == nil {
			result.Sources = map[string]SourceMeta{}
		}
		meta := result.Sources[providerName]
		meta.Error = err.Error()
		result.Sources[providerName] = meta
		return result
	}
	return modelsFromIDs(snapshot.Models, SourceHarnessPTY, snapshot.CapturedAt, discoveryIdentity{
		Provider:       providerName,
		ProviderType:   providerType,
		Harness:        providerType,
		EndpointName:   providerName,
		ServerInstance: providerName,
	})
}

type service struct {
	opts     ServiceOptions
	registry *harnesses.Registry
	hub      *sessionHub

	// lastDecisionMu guards lastDecisionCache.
	lastDecisionMu sync.RWMutex
	// lastDecisionCache maps route key → (decision, time). Populated by
	// ResolveRoute; read by RouteStatus.
	lastDecisionCache map[string]lastDecisionEntry

	routeHealth      *routehealth.Store
	routeLeases      *routehealth.LeaseStore
	routeUtilization *routehealth.UtilizationStore

	// catalog is the service-scope model-catalog cache. Populated lazily
	// on first use by routing + chat paths; shared across requests so the
	// same endpoint isn't probed per-dispatch during a drain. See
	// service_catalog_cache.go.
	catalog *catalogCache

	// routingQuality records routing-quality observations (ADR-006 §5).
	// Populated by Execute on every request and read by RouteStatus and
	// UsageReport.
	routingQuality *routingQualityStore

	// providerQuota is the per-provider quota state machine. Routing reads
	// the projected exhausted set on every Resolve so quota_exhausted
	// providers are excluded from candidate selection.
	providerQuota *ProviderQuotaStateStore

	// providerBurnRate observes per-provider token consumption against the
	// operator-configured daily_token_budget and pre-emptively transitions
	// providers into quota_exhausted when local burn-rate predicts the
	// budget will be exceeded before the next UTC daily reset.
	providerBurnRate *ProviderBurnRateTracker

	runtime serviceimpl.Runtime
}

const (
	defaultCatalogProbeTimeout  = 2 * time.Second
	defaultCatalogReloadTimeout = 30 * time.Second
)

func (o ServiceOptions) catalogProbeTimeout() time.Duration {
	if o.CatalogProbeTimeout > 0 {
		return o.CatalogProbeTimeout
	}
	return defaultCatalogProbeTimeout
}

func (o ServiceOptions) catalogRefreshTimeout() time.Duration {
	if o.CatalogReloadTimeout > 0 {
		return o.CatalogReloadTimeout
	}
	return defaultCatalogReloadTimeout
}

func (s *service) now() time.Time {
	return s.runtime.Now()
}

// lastDecisionEntry caches the most recent RouteDecision for a route key.
type lastDecisionEntry struct {
	decision *RouteDecision
	at       time.Time
}

// loadServiceConfig, when non-nil, is called by New to load a ServiceConfig
// from a directory path when opts.ServiceConfig is nil. It is registered by
// the config package via init() to break the import cycle (config imports root).
var loadServiceConfig func(dir string) (ServiceConfig, error)

// RegisterConfigLoader is called by the config package's init() to install the
// config-loading function. Do not call this from application code.
func RegisterConfigLoader(fn func(dir string) (ServiceConfig, error)) {
	loadServiceConfig = fn
}

// New constructs a FizeauService. When opts.ServiceConfig is nil, New attempts to
// load configuration automatically:
//  1. If opts.ConfigPath is non-empty, load from filepath.Dir(opts.ConfigPath).
//  2. Otherwise, load from the default global config location.
//
// Automatic loading requires the config package to be imported somewhere in the
// binary (it registers the loader via init). If the config package is not
// imported and ServiceConfig is nil, the service starts without provider config
// (ListProviders/HealthCheck will return errors until config is injected).
func New(opts ServiceOptions) (FizeauService, error) {
	if opts.ServiceConfig == nil && loadServiceConfig != nil && shouldAutoLoadServiceConfig(opts) {
		dir := ""
		if opts.ConfigPath != "" {
			dir = filepath.Dir(opts.ConfigPath)
		}
		sc, err := loadServiceConfig(dir)
		if err != nil {
			return nil, fmt.Errorf("agent.New: load config: %w", err)
		}
		opts.ServiceConfig = sc
	}
	svc := &service{
		opts:             opts,
		registry:         harnesses.NewRegistry(),
		hub:              newSessionHub(),
		runtime:          serviceimpl.NewRuntime(serviceimpl.RuntimeDeps{}),
		catalog:          newCatalogCache(catalogCacheOptions{AsyncRefreshTimeout: opts.catalogRefreshTimeout()}),
		routeHealth:      routehealth.NewStore(),
		routeLeases:      routehealth.NewLeaseStore(),
		routeUtilization: routehealth.NewUtilizationStore(),
		routingQuality:   newRoutingQualityStore(),
		providerQuota:    NewProviderQuotaStateStore(),
		providerBurnRate: NewProviderBurnRateTracker(),
	}
	// Hydrate per-provider daily_token_budget from ServiceConfig so the
	// burn-rate tracker can predict exhaustion before the upstream quota
	// signal arrives.
	if opts.ServiceConfig != nil {
		for _, name := range opts.ServiceConfig.ProviderNames() {
			entry, ok := opts.ServiceConfig.Provider(name)
			if !ok {
				continue
			}
			if entry.DailyTokenBudget > 0 {
				svc.providerBurnRate.SetBudget(name, entry.DailyTokenBudget)
			}
		}
	}
	svc.reapStaleHarnessSessions()
	svc.ensurePrimaryQuotaRefresh(context.Background(), quotaRefreshStartup)
	svc.startPrimaryQuotaRefreshWorker()
	svc.startQuotaRecoveryProbeLoop()
	return svc, nil
}

// harnessType returns "native" for HTTP/embedded harnesses, "subprocess" for CLI-invoked ones.
func harnessType(cfg harnesses.HarnessConfig) string {
	if harnessRunsInProcessOrHTTP(cfg) {
		return "native"
	}
	return "subprocess"
}

