	svc := &service{opts: ServiceOptions{}, registry: registry}

	inputs := svc.buildRoutingInputsWithCatalog(context.Background(), nil)
	claudeEntry, ok := findRoutingHarnessEntry(inputs.Harnesses, "claude")
