			view := modeleligibility.Resolve(modelID, true, status, cat)
			eligibility[modelID] = routing.ModelEligibility{
				Power:        view.Power,
				ExactPinOnly: view.ExactPinOnly,
				AutoRoutable: view.AutoRoutable,
