}

func (m discoveredModel) identityKey() string {
	return strings.Join([]string{
		m.Provider,
		m.ProviderType,
		m.Harness,
		m.ID,
		m.EndpointName,
		m.EndpointBaseURL,
		m.ServerInstance,
	}, "\x00")
}

